#!/usr/bin/env node
/* Ingest the faculty practice problem sets embedded at the end of the OST 520 lecture PDFs.
   Sources (all under 26 Fall/OST 520/_inputs):
     - Week 1/lectures/OST520 (007) L - Vitamins - Wilkins.pdf, pp.17-26  "Wilkins Problem Set"
     - Week 1/lectures/OST520 (015) L - Population Genetics - Wilkins.pdf, pp.12-20  (two sets)
     - Week 1/lectures/OST520 (006) L - Mendelian Modes of Inheritance - Wilkins.pdf, pp.11-19
     - Week 1/lectures/OST520 (014) L - Factors Modulating Inheritance - Wilkins.pdf, pp.18-20
     - Refresher Materials/6 - Carbohydrates - Part 2.pdf, pp.11-14
     - Collaborative Application Session 1 (Aug 26 2026) cases
   Every item carries source:"faculty-practice" and a sourceRef naming the file and original number.
   Questions whose answer key is published by the faculty are marked keyed:true.
   Figure-dependent items that cannot be rendered as text are listed in SKIPPED below. */
const fs = require("fs");

const questions = [
  // ---------- OST520 (007) Wilkins Problem Set: Introduction to Metabolism / Carbohydrates / Vitamins ----------
  {id:"FP-01",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L001"],concepts:["stages-of-catabolism","anabolism-vs-catabolism"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q1",keyed:true,stem:"Which of the following statements about metabolism is correct?",options:["Plasma ATP levels regulate the various tissue responses to metabolic needs","The brain prefers to use lipids for energy production","The heart is the primary organ of metabolism","Acetyl CoA is produced from the breakdown of carbohydrates, fats, and proteins","Catabolic processes yield NADPH, a form of reducing power for the electron transport chain"],answer:3,rationale:"Acetyl-CoA is the convergence point of all three fuel classes; its carbons then enter the TCA cycle for complete oxidation to CO&#8322; and H&#8322;O.<br><br><strong>The trap:</strong> ATP is not circulated in blood, so plasma ATP regulates nothing. The brain runs on glucose (ketones in prolonged fasting), the liver is the primary metabolic organ, and NADPH is anabolic reducing power that the ETC does not use."},
  {id:"FP-02",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L001","L002"],concepts:["nad-vs-fad","anabolism-vs-catabolism"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q2",keyed:true,stem:"Which of the following are the main forms of reducing power produced by catabolism and used by the electron transport chain for ATP production?",options:["FADH&#8322; only","NADH only","NADPH only","FADH&#8322; and NADH","FADH&#8322;, NADH, and NADPH"],answer:3,rationale:"Catabolism generates NADH and FADH&#8322;, and both deliver electrons to the ETC.<br><br><strong>The trap:</strong> NADPH is genuinely reducing power, but it is kept reduced (NADP&#8314;/NADPH about 1/10 to 1/100) precisely so it can drive reductive biosynthesis. It is not an ETC substrate."},
  {id:"FP-03",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L001"],concepts:["carb-digestion","sugar-absorption"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q8",keyed:true,stem:"Which of the following statements is true regarding the digestion and absorption of dietary carbohydrates?",options:["Most long chain carbohydrates are broken down in the stomach","The mucosal cells of the intestines express the salivary amylases necessary to break down starches","Absorption of fructose requires a Na&#8314;/K&#8314; ATPase","Galactose and glucose use the same route of uptake into the enterocytes","People who cannot digest milk sugar lack the enzyme sucrase"],answer:3,rationale:"Glucose and galactose share <strong>SGLT1</strong>, the Na&#8314;-dependent cotransporter of the brush border. Fructose enters separately by facilitated diffusion on GLUT5 and needs no Na&#8314; gradient.<br><br><strong>The trap:</strong> gastric HCl inactivates swallowed amylase, so essentially no carbohydrate digestion happens in the stomach, and lactose intolerance is a deficiency of <em>lactase</em>, not sucrase."},
  {id:"FP-04",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L001"],concepts:["carb-digestion","sugar-absorption"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q10",keyed:true,stem:"The enterocytes (intestinal mucosal cells) can directly absorb which of the following carbohydrates?",options:["Glucose","Lactose","Maltose","Starch","Sucrose"],answer:0,rationale:"Only <strong>monosaccharides</strong> cross the enterocyte membrane &mdash; glucose, galactose, and fructose. Everything larger must first be hydrolysed.<br><br><strong>The trap:</strong> lactose, maltose, and sucrose are disaccharides that require brush-border disaccharidases; starch requires amylase first and then those same disaccharidases."},
  {id:"FP-05",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L002"],concepts:["enzyme-classes","oxidation-states"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q14",keyed:true,stem:"What is the typical naming convention for an enzyme that uses NADP&#8314;/NADPH, regardless of which direction the reaction is proceeding?",options:["Dehydratase, named for the molecule losing the water molecule","Dehydrogenase, named for the more reduced molecule","Hydratase, named for the molecule receiving the water molecule","Reductase, named for the more oxidized molecule","Synthetase, named for the product of the reaction"],answer:3,rationale:"Wilkins&rsquo; convention: enzymes using the NADP&#8314;/NADPH pair are <strong>reductases</strong>, named for the more oxidized partner. Enzymes using NAD&#8314;/NADH are <strong>dehydrogenases</strong>, named for the more reduced partner.<br><br><strong>The trap:</strong> the name does not flip when the reaction runs backwards &mdash; the cofactor identity, not the direction, sets the name."},
  {id:"FP-06",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L002"],concepts:["carbon-numbering","oxidation-states"],type:"mcq",context:"A 12-carbon fatty acid is drawn with its carbons numbered 1 through 12, beginning at the carboxylic acid carbon.",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q15",keyed:true,stem:"Which numbered carbon would also be referred to as the beta (&beta;) carbon?",options:["Carbon 1","Carbon 2","Carbon 3","Carbon 4","Carbon 12"],answer:2,rationale:"The carboxylic acid carbon is C1 and carries <strong>no Greek letter at all</strong>. Counting from there, C2 is alpha and C3 is beta.<br><br><strong>The trap:</strong> the Greek series starts on the carbon <em>next to</em> the acid, so alpha is C2 and not C1. The terminal methyl is always omega no matter how long the chain is."},
  {id:"FP-07",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L002","RR1"],concepts:["glycolysis-steps","high-energy-phosphate"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q17",keyed:true,stem:"A glycolytic reaction that yields a high-energy phosphate compound as a product is catalyzed by:",options:["Phosphoglycerate mutase","Succinyl-CoA synthetase","Triose phosphate isomerase","Glyceraldehyde-3-P dehydrogenase","Fructose-1,6-bisP aldolase"],answer:3,rationale:"GAPDH produces <strong>1,3-bisphosphoglycerate</strong>. The phosphate on C1 is an acyl phosphate (a phosphoanhydride), and hydrolysing it is what pays for ATP at the next step, phosphoglycerate kinase.<br><br><strong>The trap:</strong> succinyl-CoA synthetase does make a high-energy compound, but it belongs to the TCA cycle, not glycolysis. The mutase and isomerase rearrange without changing bond energy."},
  {id:"FP-08",topic:"Biochemistry",src:"B",unit:"UE1",covers:["RR1","RR5"],concepts:["shuttles","lactate-and-nad-regeneration"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q18",keyed:true,stem:"For glycolysis to continue there must always be a cytosolic pool of NAD&#8314;. Under aerobic conditions, how is that pool maintained?",options:["The glyceraldehyde 3-P dehydrogenase reaction regenerates cytosolic NAD&#8314;","The lactate dehydrogenase reaction regenerates cytosolic NAD&#8314;","The malate-aspartate shuttle or glycerol phosphate shuttle regenerate cytosolic NAD&#8314;","The pyruvate dehydrogenase complex regenerates cytosolic NAD&#8314;"],answer:2,rationale:"With oxygen present the ETC is running, so the two shuttles can hand cytosolic NADH electrons to the mitochondrion and return <strong>NAD&#8314;</strong> to the cytosol.<br><br><strong>The trap:</strong> lactate dehydrogenase is the right answer to the <em>anaerobic</em> version of this question. GAPDH consumes NAD&#8314; rather than regenerating it, and PDH works in the matrix on a different pool."},
  {id:"FP-09",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L002","RR1"],concepts:["glycolysis-steps","oxidation-states"],type:"mcq",context:"Two triose phosphates have identical molecular formulas and differ only in arrangement: one carries a ketone group, the other an aldehyde group.",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q19 (figure rendered as text)",keyed:true,stem:"Which molecule continues through the second half of glycolysis, and why?",options:["The ketone-bearing isomer, because it contains a high energy phosphate bond","The ketone-bearing isomer, because its keto group can be oxidized to a secondary alcohol","The aldehyde-bearing isomer, because it contains a high energy phosphate bond","The aldehyde-bearing isomer, because its aldehyde group can be oxidized to a carboxylic acid"],answer:3,rationale:"The two are DHAP and glyceraldehyde 3-phosphate, interconverted by an isomerase. Only <strong>G3P</strong> proceeds, because the very next step (GAPDH) oxidizes its aldehyde to a carboxylic acid &mdash; the defining move of a catabolic pathway.<br><br><strong>The trap:</strong> a ketone cannot be oxidized further without breaking a carbon-carbon bond, and reduction, not oxidation, converts a ketone to a secondary alcohol. Neither triose carries a high-energy phosphate yet; that bond is created at the GAPDH step."},
  {id:"FP-10",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L002","RR1"],concepts:["glycolysis-steps","high-energy-phosphate"],type:"mcq",context:"Three consecutive glycolytic enzymes act in sequence: X converts glyceraldehyde 3-phosphate to a doubly phosphorylated intermediate, Y converts that intermediate to a singly phosphorylated three-carbon acid, and Z relocates the remaining phosphate from carbon 3 to carbon 2.",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q20 (figure rendered as text)",keyed:true,stem:"What is the correct series of reaction types carried out by enzymes X, Y, and Z?",options:["X: reduction and dephosphorylation; Y: ATP utilization; Z: reduction","X: redox reaction and phosphorylation; Y: ATP formation; Z: isomerization","X: ATP utilization; Y: dehydration; Z: enol formation","X: ATP formation; Y: decarboxylation; Z: hydration","X: redox reaction and hydration; Y: hydration; Z: enol formation"],answer:1,rationale:"X is GAPDH: it oxidizes the aldehyde and phosphorylates the resulting acid, giving 1,3-BPG (<strong>redox plus phosphorylation</strong>). Y is phosphoglycerate kinase, handing that phosphate to ADP (<strong>ATP formation</strong>). Z is phosphoglycerate mutase, moving the phosphate from C3 to C2, so substrate and product are isomers (<strong>isomerization</strong>).<br><br><strong>The trap:</strong> read what changed between the molecules rather than trying to recall the pathway by rote &mdash; same formula on both sides of Z means isomerization."},
  {id:"FP-11",topic:"Biochemistry",src:"B",unit:"UE1",covers:["RR1"],concepts:["glucokinase-vs-hexokinase","glycolysis-regulation"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q21",keyed:true,stem:"A purified enzyme requires glucose and ATP as substrates and is inhibited by glucose 6-phosphate. Which enzyme is it?",options:["Glucokinase","Hexokinase","Phosphofructokinase 1 (PFK1)","Phosphoglucoisomerase","Glucokinase or hexokinase; the tests cannot distinguish them"],answer:1,rationale:"Both isozymes phosphorylate glucose using ATP, so the discriminator is the <strong>product inhibition</strong>: hexokinase is switched off by glucose 6-phosphate, which stops a muscle cell importing more glucose than it can use.<br><br><strong>The trap:</strong> glucokinase is deliberately <em>not</em> product-inhibited, because the liver must clear all the glucose arriving in the portal blood and either burn it or store it."},
  {id:"FP-12",topic:"Biochemistry",src:"B",unit:"UE1",covers:["RR1"],concepts:["glycolysis-steps","high-energy-phosphate"],type:"worked",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q23",keyed:true,options:[],answer:null,stem:"In two of the last three reactions of glycolysis the phosphate group is switched from carbon 3 to carbon 2 and the molecule is then dehydrated to form an enol. Why are these steps necessary?",rationale:"To turn the phosphate into a <strong>good leaving group</strong>. An alcohol phosphate is a poor leaving group, so 3-phosphoglycerate cannot be used to phosphorylate ADP. Moving the phosphate to C2 and then dehydrating raises its leaving-group potential to that of an <strong>enol phosphate</strong> (phosphoenolpyruvate), which is now energetic enough to drive ATP synthesis at pyruvate kinase.<br><br>These steps do a second job as well: when the phosphate finally leaves, the enol collapses to a keto group on the alpha carbon. That alpha-keto arrangement is what allows the carboxyl group to be removed later by the pyruvate dehydrogenase complex, should the pyruvate reach the mitochondrion."},
  {id:"FP-13",topic:"Biochemistry",src:"B",unit:"UE1",covers:["RR1","RR5"],concepts:["lactate-and-nad-regeneration","shuttles"],type:"worked",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q24",keyed:true,options:[],answer:null,stem:"Briefly explain why molecular oxygen (O&#8322;) controls the glycolytic pathway, that is, aerobic versus anaerobic glycolysis.",rationale:"Everything follows from whether the ETC can run.<br><br><strong>Without oxygen:</strong> the ETC stops, so oxidative phosphorylation makes no ATP and the TCA cycle also halts, because its NADH and FADH&#8322; have nowhere to unload and NAD&#8314;/FAD are never regenerated. Glycolysis becomes the only pathway still yielding ATP directly. But glycolysis itself needs cytosolic NAD&#8314; for GAPDH, and the shuttles cannot work with the ETC down. So an eleventh step is added: <strong>lactate dehydrogenase</strong> re-oxidizes NADH to NAD&#8314;, letting glycolysis continue.<br><br><strong>With oxygen:</strong> the ETC runs, so the malate-aspartate and glycerol phosphate shuttles carry the electrons of cytosolic NADH into the mitochondrion and return NAD&#8314; to the cytosol. GAPDH keeps working, lactate is not needed, and the pyruvate goes on to PDH and the TCA cycle."},

  // ---------- Carbohydrate digestion enzymes (Application Session 1 cases 5 and 6) ----------
  {id:"FP-14",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L001"],concepts:["carb-digestion"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Collaborative Application Session 1 (Aug 26 2026) Case 5",keyed:false,stem:"A 22-year-old student begins chewing a piece of bread. As the bread is mixed with saliva, which enzyme begins the digestion of its starch content?",options:["Lactase","Maltase","Pancreatic &alpha;-amylase","Salivary &alpha;-amylase","Sucrase"],answer:3,rationale:"<strong>Salivary &alpha;-amylase</strong> starts hydrolysing the &alpha;(1&rarr;4) bonds of starch in the mouth, producing shorter dextrins.<br><br><strong>The trap:</strong> its contribution is brief, because gastric HCl inactivates it once the bolus is swallowed. Maltase, sucrase, and lactase are brush-border disaccharidases that act much later, on the products."},
  {id:"FP-15",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L001"],concepts:["carb-digestion"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Collaborative Application Session 1 (Aug 26 2026) Case 6",keyed:false,stem:"A 45-year-old patient undergoes pancreatic surgery and subsequently develops difficulty digesting carbohydrates. Which enzyme normally provides the major enzymatic digestion of dietary starch in the small intestine?",options:["Salivary amylase","Pancreatic &alpha;-amylase","Lactase","Isomaltase","Sucrase"],answer:1,rationale:"<strong>Pancreatic &alpha;-amylase</strong> secreted into the duodenum does the bulk of starch digestion, which is why losing pancreatic exocrine function impairs it.<br><br><strong>The trap:</strong> salivary amylase starts the job but is destroyed in the stomach; the disaccharidases finish the job but cannot attack polysaccharides."},
  {id:"FP-16",topic:"Biochemistry",src:"B",unit:"UE1",covers:["L001"],concepts:["carb-digestion","sugar-absorption"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Wilkins Problem Set (007 Vitamins) Q8 distractor E, expanded",keyed:false,stem:"An adult develops bloating, cramping, and osmotic diarrhoea within an hour of drinking milk. Which enzyme is deficient, and where does it normally act?",options:["Lactase, at the intestinal brush border","Sucrase, in pancreatic secretions","Salivary amylase, in the mouth","Pancreatic amylase, in the duodenal lumen","Isomaltase, in the gastric mucosa"],answer:0,rationale:"Lactose is a disaccharide, so it cannot be absorbed intact; <strong>lactase</strong> on the enterocyte brush border must split it into glucose and galactose. Undigested lactose stays osmotically active and is fermented by colonic bacteria.<br><br><strong>The trap:</strong> the disaccharidases are membrane-bound enzymes of the enterocyte surface, not pancreatic or gastric secretions."},

  // ---------- Metabolite-pattern reasoning (Application Session 1 cases 9 and 10) ----------
  {id:"FP-17",topic:"Biochemistry",src:"B",unit:"UE1",covers:["RR1"],concepts:["glycolysis-steps","enzyme-deficiency-pattern"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Collaborative Application Session 1 (Aug 26 2026) Case 9",keyed:false,stem:"A patient presents with lack of energy and very low haemoglobin. His red blood cells show a high level of phosphoenolpyruvate with little pyruvate produced and decreased ATP. A mutation in which glycolytic enzyme best explains this?",options:["Glyceraldehyde 3-phosphate dehydrogenase","Glucokinase","Phosphofructokinase","Enolase","Pyruvate kinase"],answer:4,rationale:"Substrate piles up <strong>immediately upstream</strong> of a block. PEP is the substrate of pyruvate kinase, so PEP accumulation with little pyruvate localizes the defect there; losing that step also costs the cell ATP, and red cells with no mitochondria cannot compensate, hence the haemolytic anaemia.<br><br><strong>The trap:</strong> an enolase block would accumulate 2-phosphoglycerate instead, because enolase is the enzyme that <em>makes</em> PEP."},
  {id:"FP-18",topic:"Biochemistry",src:"B",unit:"UE1",covers:["RR1"],concepts:["glucokinase-vs-hexokinase","enzyme-deficiency-pattern"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Collaborative Application Session 1 (Aug 26 2026) Case 10",keyed:false,stem:"A 19-year-old woman has been anaemic since birth. Analysis of her red blood cell glycolytic intermediates shows that all intermediates from glucose 6-phosphate onward are lower than normal. A mutation in which glycolytic enzyme best explains this?",options:["Glyceraldehyde 3-phosphate dehydrogenase","Hexokinase","Phosphofructokinase","Phosphoglycerate kinase","Pyruvate kinase"],answer:1,rationale:"When <strong>everything downstream of and including G6P is low</strong>, the block must be at the step that produces G6P. In the red cell that step is hexokinase, which traps glucose on entry.<br><br><strong>The trap:</strong> a block further down the pathway would <em>raise</em> the intermediates above it while lowering those below. Read the pattern, not just the lowest value."},

  // ---------- Probability and nucleoside analogs (Application Session 1) ----------
  {id:"FP-19",topic:"Genetics",src:"G",unit:"UE1",covers:["L006"],concepts:["probability-rules","autosomal-recessive"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Collaborative Application Session 1 (Aug 26 2026) Case 13",keyed:false,stem:"Two parents are carriers of the same autosomal recessive disorder. What is the probability that their next three children will all be unaffected?",options:["9/16","27/64","3/4","1/64"],answer:1,rationale:"Each pregnancy independently carries a 3/4 chance of an unaffected child. The <strong>product rule</strong> for several future events gives (3/4)&sup3; = 27/64.<br><br><strong>The trap:</strong> the product rule applies only to predicting future events together. It is never used to revise the risk of one pregnancy on the basis of how earlier children turned out."},
  {id:"FP-20",topic:"Genetics",src:"G",unit:"UE1",covers:["L003"],concepts:["dna-replication-enzymes","nucleoside-analogs"],type:"mcq",context:"A 5-year-old child is being treated for acute lymphoblastic leukaemia with chemotherapy that includes cytosine arabinoside (cytarabine, araC), a nucleoside analog.",source:"faculty-practice",sourceRef:"Collaborative Application Session 1 (Aug 26 2026) Case 2 Q1",keyed:false,stem:"Which of the following enzymes will incorporate this drug into growing chains of DNA?",options:["RNA polymerase II","DNA polymerase","Primase","Ligase","Topoisomerase I"],answer:1,rationale:"AraC is a deoxycytidine analog. Once the cell phosphorylates it to the triphosphate, <strong>DNA polymerase</strong> accepts it as a substrate and inserts it into the growing strand, where its arabinose sugar stalls further extension.<br><br><strong>The trap:</strong> the drug is given as a nucleoside because a charged nucleotide could not cross the membrane; it is the cell&rsquo;s own kinases that activate it."},

  // ---------- OST520 (015) Population Genetics Practice Questions ----------
  {id:"FP-21",topic:"Genetics",src:"G",unit:"UE1",covers:["L015","L006"],concepts:["hardy-weinberg","carrier-probability","probability-rules"],type:"mcq",context:"A prenatal patient presents for counselling at 15 weeks with a family history of a rare autosomal recessive lipodystrophy; her sister died of it. The condition occurs in 1 in 10,000,000 individuals. Consanguinity with her partner is denied.",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q1a-b",keyed:true,stem:"What is the risk to this couple's fetus of being affected?",options:["1/9486","1/6324","1/3162","1/2371","1/1581"],answer:0,rationale:"Three independent factors multiply. The patient is unaffected with two carrier parents, so she is a carrier with probability <strong>2/3</strong>. For her partner, q&sup2; = 1/10,000,000 gives q = 1/3162, so the carrier frequency 2pq is about <strong>1/1581</strong>. If both carry it, the chance both transmit is <strong>1/4</strong>. Multiplying: (2/3)(1/1581)(1/4) = 1/9486.<br><br><strong>The trap:</strong> the sister's diagnosis tells you about the patient's own risk, but her partner is from the general population, so only Hardy-Weinberg can supply his."},
  {id:"FP-22",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["hardy-weinberg","carrier-probability"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q2",keyed:true,stem:"A Caucasian woman has cystic fibrosis with two mutant alleles. The population incidence is 1 in 400 among Caucasians. She marries an unrelated Caucasian man. What is the likelihood that they will have a fetus affected with CF?",options:["1/10","1/20","1/40","1/80","1/400"],answer:1,rationale:"q&sup2; = 1/400, so q = 1/20 and the carrier frequency 2pq is about <strong>1/10</strong>. Because the mother is affected she transmits a mutant allele to every child, so her factor is 1. The father contributes (1/10 carrier) &times; (1/2 transmission) = 1/20.<br><br><strong>The trap:</strong> do not put a 1/4 in this calculation. A 1/4 applies to carrier &times; carrier; here one parent is homozygous affected."},
  {id:"FP-23",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["allele-frequency"],type:"mcq",context:"In a clinical study, 100 subjects are genotyped at a locus hypothesized to be associated with cancer: AA in 30, AB in 25, BB in 45.",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q3",keyed:true,stem:"What is the frequency of the B allele?",options:["0.45","0.575","0.25","0.70","0.115"],answer:1,rationale:"Count alleles directly: each AB contributes one B and each BB contributes two, giving 25 + 90 = <strong>115 B alleles</strong> out of 200 total alleles in 100 diploid people, so 115/200 = 0.575.<br><br><strong>The trap:</strong> Hardy-Weinberg is not needed and would be wrong to invoke here. The genotypes were counted, so the allele frequency is a matter of arithmetic, not of assuming equilibrium."},
  {id:"FP-24",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["hardy-weinberg","autosomal-dominant"],type:"mcq",context:"A birth defect results from a parasitic infection during pregnancy. A parasite resistance allele occurs in 20% of the population and is autosomal dominant.",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q4",keyed:true,stem:"What percentage of the population is predicted to be resistant to the parasite?",options:["20%","4%","36%","80%","96%"],answer:2,rationale:"You are given p = 0.20, so q = 0.80. Because resistance is dominant, resistant people are both the homozygotes and the heterozygotes: p&sup2; + 2pq = 0.04 + 0.32 = <strong>0.36</strong>.<br><br><strong>The trap:</strong> 20% is the allele frequency, not the phenotype frequency, and 4% counts only the homozygotes. A dominant phenotype always needs the 2pq term as well."},
  {id:"FP-25",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["hardy-weinberg","carrier-probability"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q5",keyed:true,stem:"Among the African-American population the allele frequency of the sickle-cell mutation is about 4%. Assuming Hardy-Weinberg equilibrium, what are the expected frequencies of affected individuals and of carriers?",options:["Affected about 0.0016; carriers about 0.077","Affected about 0.04; carriers about 0.16","Affected about 0.0016; carriers about 0.0032","Affected about 0.08; carriers about 0.0016","Affected about 0.16; carriers about 0.48"],answer:0,rationale:"q = 0.04, so affected homozygotes are q&sup2; = <strong>0.0016</strong> and carriers are 2pq = 2(0.96)(0.04), about <strong>0.077</strong>.<br><br><strong>The trap:</strong> carriers outnumber affected individuals by roughly 2/q, which for a rare allele is a very large factor. That ratio is the whole reason carrier screening exists."},
  {id:"FP-26",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["hardy-weinberg","carrier-probability"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q6",keyed:true,stem:"The incidence of Tay-Sachs disease, an autosomal recessive disorder, is about 1/3600 in Ashkenazi Jewish populations. What is the carrier frequency in these populations?",options:["1/30","1/60","1/120","1/1800","1/3600"],answer:0,rationale:"q&sup2; = 1/3600 gives q = <strong>1/60</strong>. Carriers are 2pq, and with p close to 1 this is about 2/60 = <strong>1/30</strong>.<br><br><strong>The trap:</strong> 1/60 is the allele frequency, not the carrier frequency. For a rare recessive the carrier frequency is roughly twice the allele frequency."},
  {id:"FP-27",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["hardy-weinberg","autosomal-dominant"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q7",keyed:true,stem:"Familial hypercholesterolemia is autosomal dominant with a prevalence of about 1 in 400 in Caucasian populations. What is the mutant allele frequency, and what is the frequency of affected homozygotes?",options:["Allele about 1/800; homozygotes about 1/640,000","Allele about 1/400; homozygotes about 1/160,000","Allele about 1/200; homozygotes about 1/40,000","Allele about 1/800; homozygotes about 1/1600","Allele about 1/20; homozygotes about 1/400"],answer:0,rationale:"For a rare dominant, essentially all affected people are heterozygotes, so 2pq = 1/400 with q close to 1 gives p = <strong>1/800</strong>. Homozygotes are p&sup2; = <strong>1/640,000</strong>.<br><br><strong>The trap:</strong> for a dominant condition the disease frequency is 2pq, not p&sup2;. Reaching for p&sup2; is the standard error, and it is why homozygous dominant disease is vanishingly rare."},
  {id:"FP-28",topic:"Genetics",src:"G",unit:"UE1",covers:["L015","L006"],concepts:["x-linked-recessive","hardy-weinberg"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q8",keyed:true,stem:"Hemophilia A, an X-linked disorder of coagulation, has a prevalence of about 1 per 10,000 in males but a much lower frequency among females. Which is the most likely explanation for this difference?",options:["Females are less prone to mutation","Females are less likely to have coagulation problems","Females have two X chromosomes, whereas males have only one","Females can receive the disease gene only from their fathers, whereas males can receive it from either parent","X-inactivation in females selectively turns off the defective gene"],answer:2,rationale:"A male needs only the one mutant X to be affected, so the male frequency equals the allele frequency q. A female needs two, so her frequency is q&sup2;. With q = 1/10,000 that predicts about <strong>1 in 100,000,000</strong> females.<br><br><strong>The trap:</strong> X-inactivation is random, not selective; it cannot preferentially silence the mutant allele, though skewing can occasionally make a carrier symptomatic."},
  {id:"FP-29",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["x-linked-recessive","hardy-weinberg"],type:"mcq",context:"In some regions of Africa where malaria is endemic, the prevalence of G6PD deficiency, an X-linked recessive condition, is nearly 25% among males.",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q9",keyed:true,stem:"Assuming Hardy-Weinberg equilibrium, what are the allele frequencies and how does the frequency of affected females compare with affected males?",options:["q = 0.25 and p = 0.75; affected females 0.0625, carrier females 0.375","q = 0.5 and p = 0.5; affected females 0.25, carrier females 0.5","q = 0.25 and p = 0.75; affected females 0.25, carrier females 0.75","q = 0.125 and p = 0.875; affected females 0.0156, carrier females 0.22","q = 0.0625 and p = 0.9375; affected females 0.25, carrier females 0.117"],answer:0,rationale:"For an X-linked trait the male frequency <em>is</em> the allele frequency, so q = <strong>0.25</strong> and p = 0.75. Affected females are q&sup2; = <strong>0.0625</strong> (1 in 16) and carriers are 2pq = <strong>0.375</strong>.<br><br><strong>The trap:</strong> when q is this large, affected females are not rare at all &mdash; the usual intuition that X-linked disease is a male problem depends on q being small."},
  {id:"FP-30",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["hardy-weinberg","hw-assumptions"],type:"mcq",context:"A population shows the following genotype frequencies: A/A = 0.59, A/a = 0.19, a/a = 0.02.",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q10",keyed:true,stem:"Is this population in Hardy-Weinberg equilibrium?",options:["Yes; the frequencies satisfy p&sup2; + 2pq + q&sup2; = 1","No; the genotype frequencies sum to only 0.80 rather than 1.0","Yes, but only if the population is small","No; because 2pq is smaller than p&sup2;","It cannot be determined without knowing the allele frequencies"],answer:1,rationale:"The three genotype frequencies must account for everyone. These sum to <strong>0.80</strong>, so the population cannot be at equilibrium. Selection against homozygotes, assortative mating, or migration could explain it.<br><br><strong>The trap:</strong> 2pq being smaller than p&sup2; is perfectly normal when one allele is common, so that observation proves nothing on its own. Check the sum first."},
  {id:"FP-31",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["founder-effect","hw-assumptions"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q11",keyed:true,stem:"The Old-Order Amish community in Pennsylvania arose from a small band of people with common religious beliefs who tended to marry within their faith. The frequency of maple-syrup urine disease among them is markedly higher than in the surrounding population. This most likely represents:",options:["Reduced fitness","Founder effect","Random mating","Geographic stratification","Heterozygote advantage"],answer:1,rationale:"A <strong>founder effect</strong>: a small group carried an unrepresentative sample of alleles, and subsequent endogamy preserved those frequencies instead of diluting them into the wider population.<br><br><strong>The trap:</strong> heterozygote advantage would require the carrier state to confer a survival benefit, as it does for sickle cell in malarial regions. Nothing here suggests MSUD carriers are advantaged."},
  {id:"FP-32",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["x-linked-recessive","hardy-weinberg","carrier-probability"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Population Genetics Practice Questions (015) Q14",keyed:true,stem:"The frequency of an X-linked recessive trait among males is 0.0009 in a population at Hardy-Weinberg equilibrium. What is the frequency of the trait among females, and the expected carrier frequency?",options:["Affected females about 1 in 1,250,000; carriers about 1 in 550","Affected females 0.0009; carriers 0.0018","Affected females about 1 in 550; carriers about 1 in 1,250,000","Affected females 0.03; carriers 0.06","Affected females 0.0018; carriers 0.0009"],answer:0,rationale:"q = 0.0009 because male frequency equals the allele frequency. Affected females are q&sup2; = 0.00000081, about <strong>1 in 1,250,000</strong>. Carriers are 2pq = 0.0018, about <strong>1 in 550</strong>.<br><br><strong>The trap:</strong> squaring a small number makes it dramatically smaller, while doubling it barely changes it &mdash; which is why carriers outnumber affected females by more than a thousandfold."},

  // ---------- OST520 (015) Genetics Concepts and Calculations Problem Set ----------
  {id:"FP-33",topic:"Genetics",src:"G",unit:"UE1",covers:["L014","L006"],concepts:["mitochondrial-inheritance","heteroplasmy"],type:"mcq",context:"A family has multiple members with a degenerative disorder of muscle; some affected individuals also have vision loss and migraines, while others are only mildly affected. All the children of affected women are affected; none of the children of affected men are affected.",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q1",keyed:true,stem:"What is the BEST explanation for the variability observed in this family?",options:["Allelic heterogeneity","Reduced penetrance","Locus heterogeneity","Heteroplasmy","Skewed X-inactivation"],answer:3,rationale:"Transmission exclusively through women identifies this as mitochondrial. Within that pattern, the varying severity is explained by <strong>heteroplasmy</strong>: cells carry a mixture of mutant and normal mitochondrial genomes, and different individuals and tissues sit at different mutant loads relative to the threshold for disease.<br><br><strong>The trap:</strong> reduced penetrance is all-or-nothing and would not produce a graded range of severity within one family."},
  {id:"FP-34",topic:"Genetics",src:"G",unit:"UE1",covers:["L014"],concepts:["pleiotropy"],type:"mcq",context:"A 33-year-old man has microphthalmia, a narrow nose, absent teeth, sparse hair, and fusion of fingers 4 and 5 on both hands. Neurologic evaluation notes spasticity and speech difficulty.",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q2",keyed:true,stem:"The condition this man has is BEST described as one that exhibits:",options:["Pleiotropy","Allelic heterogeneity","Anticipation","Locus heterogeneity"],answer:0,rationale:"<strong>Pleiotropy</strong> is one mutant gene producing multiple, apparently unrelated effects across different organ systems &mdash; here eye, face, teeth, hair, limb, and nervous system.<br><br><strong>The trap:</strong> allelic and locus heterogeneity describe several genotypes converging on one phenotype. Pleiotropy is the opposite direction: one genotype fanning out into many phenotypes."},
  {id:"FP-35",topic:"Genetics",src:"G",unit:"UE1",covers:["L014","L006"],concepts:["penetrance","bayes-risk","probability-rules"],type:"mcq",context:"Hereditary breast cancer is inherited as autosomal dominant with reduced penetrance. Females with a mutant allele have about an 80% lifetime risk of developing breast cancer. A woman has an affected mother and an affected maternal grandmother.",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q3",keyed:true,stem:"What is this woman's lifetime risk of developing breast cancer?",options:["1/10","2/5","1/2","3/5"],answer:1,rationale:"Two steps multiply: a <strong>1/2</strong> chance of inheriting the allele from her affected mother, then an <strong>80%</strong> chance of expressing it. (1/2)(8/10) = <strong>2/5</strong>.<br><br><strong>The trap:</strong> the grandmother adds nothing once the mother is known to be affected &mdash; the mother's status already accounts for that branch of the pedigree. And 1/2 alone would ignore penetrance."},
  {id:"FP-36",topic:"Genetics",src:"G",unit:"UE1",covers:["L014"],concepts:["allelic-vs-locus-heterogeneity"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q4",keyed:true,stem:"A man and a woman each born with autosomal recessive hearing loss have children together; all the children have normal hearing. What is the BEST explanation?",options:["Reduced penetrance","Variable expressivity","Locus heterogeneity","Allelic heterogeneity","Somatic mosaicism"],answer:2,rationale:"<strong>Locus heterogeneity</strong>: the parents are homozygous at two different deafness loci, say d1d1D2D2 and D1D1d2d2. Every child is then a double heterozygote, carrying one normal allele at each locus, and is affected at neither.<br><br><strong>The trap:</strong> reduced penetrance is the tempting catch-all, but it would require every one of the children to escape by chance. Do not reach for penetrance whenever a pedigree breaks the expected rule."},
  {id:"FP-37",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["hardy-weinberg","autosomal-dominant"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q5",keyed:true,stem:"In a particular population, autosomal dominant retinoblastoma has a population frequency of 1/25,000. What is the allele frequency in this population?",options:["1/158","1/316","1/50,000","1/25,000,000","1/625,000,000"],answer:2,rationale:"For a rare dominant, affected individuals are essentially all heterozygotes, so disease frequency = 2pq with q close to 1. Then 2p = 1/25,000 and p = <strong>1/50,000</strong>.<br><br><strong>The trap:</strong> 1/158 and 1/316 come from taking a square root, which is the recessive manoeuvre. Square roots belong to q&sup2;, not to 2pq."},
  {id:"FP-38",topic:"Genetics",src:"G",unit:"UE1",covers:["L015","L006"],concepts:["hardy-weinberg","carrier-probability","probability-rules"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q6",keyed:true,stem:"A woman whose sister died with Tay-Sachs disease, an autosomal recessive condition, marries a man with no family history of it. The gene frequency of this condition is 1/60. What is the chance they will have an affected child?",options:["1/95","1/120","1/180","1/240","1/360"],answer:2,rationale:"Both of the woman's parents must be carriers, and since she is unaffected her carrier risk is <strong>2/3</strong>. The man comes from the general population, so his carrier risk is 2pq, about <strong>1/30</strong>. Two carriers have a <strong>1/4</strong> chance per child. (2/3)(1/30)(1/4) = <strong>1/180</strong>.<br><br><strong>The trap:</strong> 1/60 is the allele frequency; using it directly as the man's carrier risk halves the answer."},
  {id:"FP-39",topic:"Genetics",src:"G",unit:"UE1",covers:["L015","L006"],concepts:["carrier-probability","autosomal-recessive"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q7",keyed:true,stem:"A woman with hemochromatosis marries a man with no such history. Hemochromatosis is autosomal recessive with a carrier frequency of 1/8. What is the chance this couple will have an affected child?",options:["1/4","1/8","1/16","1/32","1/64"],answer:2,rationale:"The woman is affected, so she transmits a mutant allele to every child. The man is a carrier with probability <strong>1/8</strong> and would transmit with probability <strong>1/2</strong>: (1/8)(1/2) = <strong>1/16</strong>.<br><br><strong>The trap:</strong> the carrier frequency is given directly here, so there is no Hardy-Weinberg step to perform. Read carefully whether a problem hands you q or 2pq."},
  {id:"FP-40",topic:"Genetics",src:"G",unit:"UE1",covers:["L014"],concepts:["penetrance","autosomal-dominant"],type:"mcq",context:"A three-generation family has a neurologic disorder inherited as an autosomal dominant. The proband is a 35-year-old man; other affected members include one of his daughters, his sister, his brother's son, his father, and his father's sister. The brother, who is the father of the affected nephew, is unaffected.",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q10",keyed:true,stem:"Which of the following best explains why the proband's brother is unaffected?",options:["Germline mosaicism","Incomplete penetrance","New mutation in the nephew","Variable expressivity","Wild-type genotype"],answer:1,rationale:"The allele is clearly segregating through three generations, and the brother sits between two affected relatives, so he is an obligate transmitter who does not express the phenotype: <strong>incomplete penetrance</strong>.<br><br><strong>The trap:</strong> a de novo mutation in the nephew would be a remarkable coincidence in a family already carrying the allele. Prefer the explanation that uses the segregation you can already see."},
  {id:"FP-41",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["x-linked-recessive","hardy-weinberg"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q11",keyed:true,stem:"In some populations approximately 1/30 women are carriers for the X-linked trait G6PD deficiency. What is the disease frequency in males?",options:["1/15","1/30","1/60","1/450","1/900"],answer:2,rationale:"Female carriers are 2pq = 1/30, and with p close to 1 that gives q = <strong>1/60</strong>. For an X-linked trait the frequency of affected males equals the allele frequency, so <strong>1/60</strong>.<br><br><strong>The trap:</strong> the male frequency is q itself, never q&sup2;. Males are hemizygous, so there is no second allele to inherit."},
  {id:"FP-42",topic:"Genetics",src:"G",unit:"UE1",covers:["L015"],concepts:["natural-selection","heterozygote-advantage"],type:"mcq",context:"G6PD catalyses the step of the pentose phosphate pathway that produces NADPH, which maintains red cell morphology. G6PD-deficient red cells are sensitive to oxidative stress but are also less amenable to growth of the malarial parasite.",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q12",keyed:true,stem:"Given that G6PD deficiency is much more common in parts of the world where malaria is prevalent, what is the best explanation for that observation?",options:["Founder effect","Natural selection","Consanguinity","New mutation","Assortative mating"],answer:1,rationale:"<strong>Natural selection through heterozygote advantage.</strong> Low NADPH leaves glutathione oxidized, hydrogen peroxide accumulates, and denatured haemoglobin forms Heinz bodies that distort the cell &mdash; a cell the parasite grows in poorly. Where malaria is endemic that survival benefit keeps the allele frequency high.<br><br><strong>The trap:</strong> a founder effect would explain a high frequency in one isolated community, not a frequency that tracks the geography of malaria across many unrelated populations."},
  {id:"FP-43",topic:"Genetics",src:"G",unit:"UE1",covers:["L006"],concepts:["x-linked-recessive","transmission-rules"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Genetics Concepts and Calculations (015) Q14",keyed:true,stem:"If a male with G6PD deficiency has children with a woman who has no family history of G6PD deficiency, what is the most likely outcome in his offspring?",options:["Half of the girls are carriers, all the boys are affected","All the girls are carriers, half of the boys are affected","Half of the girls are carriers, none of the boys are affected","All the girls are carriers, none of the boys are affected","None of the girls are carriers, all the boys are affected"],answer:3,rationale:"He has one X, and it carries the mutation. Every daughter receives that X and is therefore an obligate <strong>carrier</strong>; every son receives his Y instead, so <strong>no son</strong> is affected.<br><br><strong>The trap:</strong> affected fathers cannot produce affected sons for an X-linked condition. That absence of male-to-male transmission is the diagnostic feature of X-linkage on a pedigree."},

  // ---------- OST520 (006) Mendelian Modes of Inheritance ----------
  {id:"FP-44",topic:"Genetics",src:"G",unit:"UE1",covers:["L006"],concepts:["autosomal-recessive","pedigree-analysis"],type:"mcq",context:"A 1-year-old girl has failure to thrive, cognitive impairment, and poor motor function. Both parents and a brother and sister are healthy. A second brother died of a similar condition at age 18 months.",source:"faculty-practice",sourceRef:"Mendelian Inheritance Problem Set (006) Q7",keyed:true,stem:"This pattern of inheritance is MOST CONSISTENT with:",options:["Autosomal dominant","Autosomal recessive","X-linked recessive","X-linked dominant","Mitochondrial"],answer:1,rationale:"The condition is absent in the parents' generation but present in the next, affects a girl and a boy, and is lethal in early childhood. Unaffected parents with affected children of both sexes is the signature of <strong>autosomal recessive</strong> inheritance.<br><br><strong>The trap:</strong> X-linked dominant would require the mother to show something, via skewed X-inactivation or mosaicism, and would not so neatly give two similarly affected children of different sexes. Prefer the simpler explanation."},
  {id:"FP-45",topic:"Genetics",src:"G",unit:"UE1",covers:["L006"],concepts:["x-linked-recessive","transmission-rules"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Mendelian Inheritance Problem Set (006) Q9",keyed:true,stem:"A man with hemophilia B, an X-linked recessive disorder, wants to know his chance of having a similarly affected son. The BEST response is:",options:["0%","25%","50%","67%","100%"],answer:0,rationale:"To father a son he must pass his <strong>Y</strong> chromosome. His mutant X goes only to daughters, every one of whom becomes an obligate carrier.<br><br><strong>The trap:</strong> the answer is 0% only because the mother's carrier status is not in play; if she were a carrier, sons could be affected through her. The question asks about what <em>he</em> transmits."},
  {id:"FP-46",topic:"Genetics",src:"G",unit:"UE1",covers:["L006"],concepts:["obligate-carrier","consanguinity","autosomal-recessive"],type:"mcq",context:"In a pedigree for an autosomal recessive condition, two first cousins have a daughter who is affected and is homozygous for two identical copies of the same mutant allele, derived from a common ancestor. The cousins' parents are a brother and sister from the second generation; their own parents form the first generation.",source:"faculty-practice",sourceRef:"Mendelian Inheritance Pedigree Case (006) Q4",keyed:true,stem:"Which conclusion is best supported?",options:["The two second-generation siblings who are the cousins' parents must both be obligate carriers","Both first-generation grandparents must be carriers","The condition must be X-linked because it appears in only one branch of the family","Neither cousin can be a carrier, since both are unaffected","All of the affected child's siblings will also be affected"],answer:0,rationale:"The child's two identical alleles trace back to one common ancestor, so each cousin must have inherited the allele through their own parent. Those two siblings are therefore <strong>obligate carriers</strong>.<br><br><strong>The trap:</strong> in the first generation only <em>one</em> of the two grandparents needs to carry the allele. These diseases are rare, so assuming both grandparents carry it multiplies an already small probability without warrant."},

  // ---------- OST520 (014) Factors Modulating Inheritance Patterns ----------
  {id:"FP-47",topic:"Genetics",src:"G",unit:"UE1",covers:["L014"],concepts:["de-novo-mutation","germline-mosaicism","penetrance"],type:"mcq",context:"A patient is diagnosed with an autosomal dominant genetic disease, but neither of his parents has any symptoms of the disease.",source:"faculty-practice",sourceRef:"Factors Modulating Inheritance Practice Questions (014) Q7",keyed:true,stem:"Which of the following is NOT a possible explanation for this scenario?",options:["A de novo mutation in the patient","Germline mosaicism in one parent","Reduced penetrance in one parent","Non-paternity","Skewed X-inactivation in the mother"],answer:4,rationale:"X-inactivation only bears on <strong>X-linked</strong> conditions, and this one is autosomal; the patient is male in any case, with a single X, so skewing could not apply to him.<br><br><strong>The trap:</strong> the other four are all genuinely possible, and de novo mutation and germline mosaicism carry very different recurrence risks for the parents &mdash; near baseline for the first, meaningfully raised for the second."},

  // ---------- Refresher Materials: Carbohydrates Part 2 tutorial ----------
  {id:"FP-48",topic:"Biochemistry",src:"B",unit:"UE1",covers:["REF3"],concepts:["stereochemistry","sugar-structure"],type:"mcq",context:"D-glucose and L-glucose differ in configuration at every chiral carbon. &alpha;-D-galactose and &beta;-D-galactose differ only at carbon 1.",source:"faculty-practice",sourceRef:"Carbohydrate Tutorial Problem Set (Refresher 6) Q2-3",keyed:true,stem:"These two pairs are, respectively:",options:["Enantiomers and anomers","Epimers and enantiomers","Anomers and epimers","Diastereomers and enantiomers","Enantiomers and epimers that are not anomers"],answer:0,rationale:"<strong>Enantiomers</strong> are non-superimposable mirror images, so they differ at every chiral centre. <strong>Epimers</strong> differ at exactly one, and <strong>anomers</strong> are the special case of epimers differing at the anomeric (former carbonyl) carbon, C1 in an aldose.<br><br><strong>The trap:</strong> &alpha;-D-glucose and &alpha;-D-galactose are epimers too, differing at C4, but they are not anomers. Every anomer pair is an epimer pair; the reverse does not hold."},
  {id:"FP-49",topic:"Biochemistry",src:"B",unit:"UE1",covers:["REF3"],concepts:["sugar-structure","glycosidic-bonds"],type:"mcq",context:"A disaccharide is formed from two &beta;-D-galactose units joined by a 1&rarr;4 linkage.",source:"faculty-practice",sourceRef:"Carbohydrate Tutorial Problem Set (Refresher 6) Q4",keyed:true,stem:"Which end is the reducing end, and why?",options:["The anomeric carbon of the second galactose, because its hydroxyl is not tied up in the glycosidic bond","The anomeric carbon of the first galactose, because it donated its hydroxyl to the bond","Neither end, because both anomeric carbons are committed to the glycosidic bond","Carbon 4 of the second galactose, because that hydroxyl is free","Both ends, because galactose is an aldose"],answer:0,rationale:"A reducing end needs a <strong>free anomeric carbon</strong> that can open back to the aldehyde. In a 1&rarr;4 linkage the first sugar's C1 is committed to the bond, so the reducing end is the second sugar's C1.<br><br><strong>The trap:</strong> sucrose is the classic non-reducing disaccharide precisely because its linkage ties up both anomeric carbons. Being an aldose is not sufficient on its own."},
  {id:"FP-50",topic:"Biochemistry",src:"B",unit:"UE1",covers:["REF3","L001"],concepts:["glycosidic-bonds","carb-digestion"],type:"mcq",context:"",source:"faculty-practice",sourceRef:"Carbohydrate Tutorial (Refresher 6) with Wilkins Problem Set (007) Q9",keyed:true,stem:"Humans hydrolyse the &alpha;(1&rarr;4) bonds of starch but not the &beta;(1&rarr;4) bonds of cellulose, yet we digest lactose perfectly well even though it also contains a &beta;(1&rarr;4) bond. What explains this?",options:["We have one specific brush-border enzyme, lactase, for that galactosidic bond, but none for the glucosidic bonds of cellulose","Cellulose bonds are converted to the &alpha; configuration in the gut lumen","Pancreatic amylase cleaves &beta; bonds only at intestinal pH","Cellulose is absorbed intact across the enterocyte and excreted unchanged","Lactose is cleaved by salivary amylase before it reaches the intestine"],answer:0,rationale:"Specificity belongs to individual enzymes, not to a whole class of bond. <strong>Lactase</strong> cleaves the one particular &beta;-galactosidic bond of lactose; we have no enzyme for the &beta;-glucosidic bonds of cellulose, which is why cellulose passes through as dietary fibre.<br><br><strong>The trap:</strong> &ldquo;humans cannot digest &beta;(1&rarr;4) bonds&rdquo; is the usual shorthand, and lactose is the exception that shows why the shorthand is imprecise."}
];

/* Figure-dependent faculty items deliberately NOT ingested (a text bank cannot pose them):
     007 Vitamins Q5, Q6  - identify coenzyme derivatives from drawn structures. Wilkins states in the
                            problem set itself that structures will NOT be asked on quizzes or exams.
     Refresher 2 (Amino Acid Tutorial) Q1-6   - identify amino acids from drawn structures.
     Refresher 3 (Nucleotide Tutorial) Q1-3   - identify nucleotides/nucleosides from drawn structures.
     Refresher 4 (Central Dogma) Q1           - read a drawn DNA structure 5'->3'.
     006 pedigree drawing exercises and the five unlabelled inheritance-pattern pedigrees.
   Faculty items already covered by an equivalent bank question, so not duplicated:
     007 Q3/Q4 (pellagra dx + treatment) -> L007-07;  Q7 (thiamine enzymes) -> L007-11;
     007 Q9 (cellulose) -> B7;  Q11 (tertiary alcohols/ketones) -> W2;  Q12 -> L007-11/L007-18;
     007 Q13 -> W21;  Q16 (LDH) -> W8;  Q22 (galactosemia) -> R5/R9/R10;
     015 Concepts Q8/Q9 -> L006 set;  006 Q10 -> L006-08;  006 Q11 -> L006-06;  006 case Q5 -> L006-07;
     014 Q1-Q5 matching set -> L014-01/08/10/14;  Refresher 4 Q2 (unambiguous code) -> G15/RT-05. */

const htmlPath="index.html", jsonPath="bank.json";
const html=fs.readFileSync(htmlPath,"utf8"), marker="let BANK = ", endMarker=";\nconst META =";
const start=html.indexOf(marker), end=html.indexOf(endMarker,start);
if(start<0||end<0) throw new Error("Embedded BANK markers not found.");
const bank=JSON.parse(html.slice(start+marker.length,end));
for(const q of questions){ const i=bank.findIndex(item=>item.id===q.id); if(i>=0) bank[i]=q; else bank.push(q); }
const topicNumbers={};
bank.forEach(q=>{ q.n=(topicNumbers[q.topic]||0)+1; topicNumbers[q.topic]=q.n; });
const serialized=JSON.stringify(bank);
fs.writeFileSync(htmlPath,html.slice(0,start+marker.length)+serialized+html.slice(end));
fs.writeFileSync(jsonPath,`${JSON.stringify(bank,null,2)}\n`);
const keyed=questions.filter(q=>q.keyed).length;
console.log(`Ingested ${questions.length} faculty practice questions (${keyed} with a published faculty answer key); bank now has ${bank.length}.`);
